INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64835415', 64835415, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN JASA KONSULTAN PENYUSUNAN KAJIAN PERENCANAAN INFRASTRUKTUR PENGEMBANGAN WILAYAH RAWAN BENCANA KEGIATAN PENGELOLAAN MANAJEMEN INTERNAL DEPUTI BIDANG INFRASTRUKTUR', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99600000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '10', '1. Pengumpulan, kompilasi, dan penataan data spasial dan non-spasial terkait wilayah rawan bencana; 2. Pengelolaan, penataan, dan penyajian data kebencanaan serta data infrastruktur sebagai bahan pendukung analisis perencanaan pengembangan infrastruktur; 3. Pelaksanaan analisis deskriptif dan tematik untuk mengidentifikasi potensi wilayah, tingkat kerawanan bencana, serta isu dan tantangan pengembangan infrastruktur; 4. Analisis awal dampak bencana terhadap kondisi, fungsi, dan kinerja infrastruktur eksisting maupun rencana pengembangan; 5. Penelaahan awal kesesuaian pengembangan infrastruktur dengan rencana tata ruang, arah kebijakan pembangunan nasional, serta kebijakan pengurangan risiko bencana; 6. Penyusunan ringkasan analisis dan rekomendasi awal perencanaan pengembangan infrastruktur yang adaptif dan berketahanan; 7. Penyusunan bahan rekomendasi kebijakan perencanaan pengembangan infrastruktur berbasis analisis spasial dan data pada wilayah rawan bencana', '1. Minimal Sarjana (S1) Perencanaan Wilayah dan Kota, Teknik Perencanaan, Teknik Sipil, Geografi, Kebencanaan, atau bidang lain yang relevan dengan perencanaan infrastruktur dan pengembangan wilayah rawan bencana; 2. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta (dibuktikan dengan kontrak); 3. Memiliki pengalaman kerja umum minimum 2 (dua) tahun di bidang sejenis perencanaan infrastruktur/perencanaan pembangunan/pengembangan wilayah yang dibuktikan melalui pengalaman kerja yang tertera dalam CV. 4. Memiliki pemahaman dasar hingga menengah mengenai prinsip perencanaan wilayah, pengembangan infrastruktur, serta pengurangan risiko bencana dan keterkaitannya dengan kebijakan pembangunan; 5. Memiliki kemampuan dasar dalam pengolahan, penataan, dan penyajian data spasial dan non-spasial sebagai bahan pendukung analisis perencanaan pengembangan infrastruktur, termasuk data kebencanaan; 6. Memiliki kemampuan dan pengalaman dalam penggunaan Sistem Informasi Geografis (SIG/GIS) untuk pengolahan, analisis, dan visualisasi data spasial, termasuk pemetaan wilayah rawan bencana dan infrastruktur eksisting, analisis keterkaitan spasial, serta kompetensi teknis khusus dan non-rutin dalam analisis spasial kebencanaan dan infrastruktur berbasis GIS sebagai bahan pendukung perencanaan infrastruktur. 7. Memiliki pengalaman kerja dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai total HPS/Pagu Anggaran; 8. Memiliki keahlian dalam integrasi dan analisis data spasial berbasis GIS (antara lain peta kebencanaan, peta infrastruktur, dan peta tata ruang) untuk mendukung penyusunan analisis awal, kajian tematik, dan rekomendasi perencanaan pengembangan infrastruktur wilayah rawan bencana; 9. Memiliki kemampuan analisis deskriptif dan tematik berbasis wilayah dalam mengidentifikasi potensi, risiko, isu, dan tantangan pengembangan infrastruktur wilayah rawan bencana; 10.Mampu menyusun laporan, ringkasan analisis, dan bahan paparan secara sistematis dan berbasis data', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1790312);
