INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64819606', 64819606, 'analyze_legacy', 'Kota Cilegon', 'kabkota', 'DINAS PEKERJAAN UMUM DAN PENATAAN RUANG', 'DED NORMALISASI SUNGAI GEREM', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Banten, Cilegon (Kota)', 99533333, 'February 2026', 'APBD', 1, 1, '1 KEGIATAN', 'Ruang Lingkup Pekerjaan : Ruang lingkup kegiatan penyusunan Detail Engineering Design (DED) Normalisasi Sungai Gerem di Kota Cilegon mencakup seluruh tahapan dan komponen teknis yang diperlukan sebagai dasar pelaksanaan pekerjaan konstruksi di lapangan. Adapun ruang lingkup kegiatan ini meliputi: A. Survei dan Investigasi Lapangan 1. Pengumpulan data topografi, hidrologi, dan hidraulik. 2. Pengukuran geometrik sungai (lebar, kedalaman, kemiringan, dll). 3. Identifikasi kondisi eksisting infrastruktur dan lingkungan sungai. 4. Inventarisasi permukiman, utilitas, serta penggunaan lahan di sepanjang sempadan sungai. B. Studi Hidrologi dan Hidraulika 1. Analisis data curah hujan, debit banjir rencana, dan pola aliran sungai. 2. Simulasi kapasitas tampung sungai terhadap debit banjir dengan berbagai skenario. 3. Penentuan dimensi saluran sungai yang optimal untuk mengurangi risiko banjir. C. Perencanaan Teknis 1. Desain normalisasi sungai, termasuk pelebaran, pendalaman, dan perkuatan tebing sungai. 2. Rencana pembangunan infrastruktur pengendali seperti tanggul, saluran pengarah, dan kolam retensi (jika diperlukan). 3. Penyesuaian desain terhadap kondisi sosial, lingkungan, dan tata ruang wilayah. D. Penyusunan Gambar Teknik 1. Gambar situasi eksisting dan gambar perencanaan desain. 2. Gambar teknis detail pekerjaan (potongan melintang, memanjang, struktur, dsb). E. Perhitungan Volume dan Rencana Anggaran Biaya (RAB) 1. Perhitungan kebutuhan material, alat, dan tenaga kerja. 2. Penyusunan RAB berdasarkan analisa harga satuan pekerjaan (AHSP) terbaru. F. Dokumen Pendukung 1. Time schedule pelaksanaan pekerjaan. 2. Kajian awal dampak lingkungan (jika diperlukan). Laporan akhir lengkap yang dapat digunakan sebagai acuan dalam proses lelang dan pelaksanaan konstruksi.', 'JASA KONSULTANSI PERENCANAAN PENGAIRAN KLUSTER 8 HARGA BIAYA FISIK 1.750.000.000 SAMPAI 2.000.000.000', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1799581);
